create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.league_configurations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check(length(name)>0), description text not null default '', team_count integer not null check(team_count between 4 and 32), seasons integer[] not null, roster_settings jsonb not null, scoring_settings jsonb not null, qualification_settings jsonb not null, source text not null check(source in ('local','nflverse','synthetic')), is_public boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.optimization_runs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, league_configuration_id uuid references public.league_configurations(id) on delete set null, status text not null check(status in ('running','completed','cancelled','failed')), source_seasons integer[] not null, objective_weights jsonb not null, input_settings jsonb not null, recommended_settings jsonb, metrics jsonb not null default '{}', candidate_count integer not null check(candidate_count>0), best_score numeric check(best_score between 0 and 100), created_at timestamptz not null default now(), completed_at timestamptz);
create index league_configurations_user_id_idx on public.league_configurations(user_id);
create index optimization_runs_user_id_idx on public.optimization_runs(user_id);
create function public.set_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger configurations_updated before update on public.league_configurations for each row execute function public.set_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,new.raw_user_meta_data->>'display_name'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.league_configurations enable row level security; alter table public.optimization_runs enable row level security;
create policy "own profile read" on public.profiles for select using(auth.uid()=id); create policy "own profile update" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "own or public config read" on public.league_configurations for select using(auth.uid()=user_id or is_public);
create policy "own config insert" on public.league_configurations for insert with check(auth.uid()=user_id); create policy "own config update" on public.league_configurations for update using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own config delete" on public.league_configurations for delete using(auth.uid()=user_id);
create policy "own run read" on public.optimization_runs for select using(auth.uid()=user_id); create policy "own run insert" on public.optimization_runs for insert with check(auth.uid()=user_id); create policy "own run update" on public.optimization_runs for update using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "own run delete" on public.optimization_runs for delete using(auth.uid()=user_id);
grant usage on schema public to anon,authenticated; grant select on public.league_configurations to anon; grant select,insert,update,delete on public.profiles,public.league_configurations,public.optimization_runs to authenticated;
